<?php
function order_items_to_deduct($analysis,$platform){$items=[];foreach($analysis['groups'] as $r){if($r['duplicate'])continue;$pid=(int)$r['product_id'];if(!isset($items[$pid]))$items[$pid]=['name'=>$r['product_name'],'orders'=>[],'qty'=>0,'before'=>$r['platform_before'],'after'=>$r['platform_after']];$items[$pid]['orders'][$r['order']]=true;$items[$pid]['qty']+=(int)$r['qty'];$items[$pid]['after']=(int)$r['platform_after'];}echo '<div class="card table-wrap"><h3>Items to Deduct</h3><p>Nonduplicate orders grouped by product. On Hand refers to '.e($platform).' sellable stock.</p><table class="table"><tr><th>Product</th><th>Contributing Order IDs</th><th>Qty to Deduct</th><th>Platform On Hand</th><th>After Posting</th></tr>';foreach($items as $item)echo '<tr><td>'.e($item['name']).'</td><td>'.e(implode(', ',array_keys($item['orders']))).'</td><td>'.$item['qty'].' pcs</td><td>'.$item['before'].' pcs</td><td><b>'.$item['after'].' pcs</b></td></tr>';if(!$items)echo '<tr><td colspan="5">All orders were already posted. No stock deduction.</td></tr>';echo '</table></div>';}
